// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 != amount2); // avoid trivial equality
        uint256 before = c.currentBetLimit();
        c.AdjustBetAmounts(amount1);
        uint256 after1 = c.currentBetLimit();
        c.AdjustBetAmounts(amount2);
        uint256 after2 = c.currentBetLimit();
        // The reference changes betLimit to amount, so after1 == amount1 and after2 == amount2, which differ if amount1 != amount2.
        // The bug (M) never changes betLimit, so after1 == after2 == before.
        // For the reference (C) we expect after1 != after2 given different amounts.
        // We assert that the two calls result in different state (i.e., the bug would always give same).
        assertTrue(after1 != after2 || after1 == before); // This holds on C: if amount1 != amount2, after1 != after2; it could also hold if after1 == before (when amount1 equals before).
        // Actually for the bug, after1 == after2 always holds, so the assertion after1 != after2 fails.
        // We need a rule that C always satisfies but M breaks. Let's assert that after a call, the new value equals the argument (the intended behavior).
        // But initial betLimit is 0; after first call it becomes amount1; after second it becomes amount2.
        // A simple property: after a sequence of two calls, if amounts differ, then final betLimit equals the last amount.
        assertTrue(c.currentBetLimit() == amount2);
    }
}

