// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 != amount2);
        uint256 before = c.currentBetLimit();
        c.AdjustBetAmounts(amount1);
        uint256 after1 = c.currentBetLimit();
        c.AdjustBetAmounts(amount2);
        uint256 after2 = c.currentBetLimit();
        assertTrue(after1 != after2 || after1 == before);
        assertTrue(c.currentBetLimit() == amount2);
    }
}
